    public record Spin(int[] parts, float perCycle) { }

    public static Spin spin(String mob) {
        return switch (mob) {
            case "pollen_puff" -> new Spin(new int[] { 2, 4, 6, 8, 10 }, -6.2832f);
            case "pollen_puff/x_ember" -> new Spin(new int[] { 2, 4, 6, 8, 10 }, -6.2832f);
            case "pollen_puff/x_rime" -> new Spin(new int[] { 2, 4, 6, 8, 10 }, -6.2832f);
            default -> null;
        };
    }

    /**
     * A boss's phase paints: 1, or n when its texture changes with its fight's phase (textures/entity/<mob>_phase<k>.png
     * and <mob>/<look>_phase<k>.png for k = 2..n, each with its _glow).
     */
    public static int phases(String mob) {
        return switch (mob) {
            case "thorn_matriarch" -> 3;
            default -> 1;
        };
    }

